<script setup>
import { ref, computed, watch, onMounted, onUnmounted, defineComponent, h } from 'vue';
import { useRoute } from 'vue-router';
import { api, time, session, role } from './api';
import { ElDrawer } from 'element-plus/es/components/drawer/index.mjs';
const paths = {
 book:'M4 19.5A2.5 2.5 0 0 1 6.5 17H20 M6.5 3H20v19H6.5A2.5 2.5 0 0 1 4 19.5v-14A2.5 2.5 0 0 1 6.5 3Z M8 7h8 M8 11h5',
 layers:'m12 2 10 5-10 5L2 7l10-5Z M2 12l10 5 10-5 M2 17l10 5 10-5',
 history:'M3 11a9 9 0 1 1 2.6 7 M3 3v8h8 M12 7v5l3 2',
 arrow:'M5 12h14 m-5-5 5 5-5 5',refresh:'M20 7v5h-5 M4 17v-5h5 M6 6a8 8 0 0 1 13 2l1 4 M4 12l1 4a8 8 0 0 0 13 2',
 search:'M21 21l-4.5-4.5 M19 11a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',
 file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8l-6-6Z M14 2v6h6 M8 13h8 M8 17h5',
 check:'m5 12 4 4L19 6',info:'M12 8h.01 M12 11v6 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',
};
const Icon=defineComponent({props:{name:String},setup:props=>()=>h('svg',{viewBox:'0 0 24 24',fill:'none',stroke:'currentColor','stroke-width':1.6,'stroke-linecap':'round','stroke-linejoin':'round','aria-hidden':true},[h('path',{d:paths[props.name]||paths.file})])});
const data=ref({memories:[],sources:[],sourceCount:0,total:0,page:1,pageSize:20,summary:{skills:0,experiences:0,sources:0,pending:0,pendingReview:0}});
const route=useRoute();
const loading=ref(true),refreshing=ref(false),error=ref(''),query=ref(''),kind=ref('all');
const state=ref('all'),review=ref('all'),page=ref(1);
const systemSkills=ref([]),systemSkill=ref(null);
const sourceId=ref(''),detail=ref(null),detailLoading=ref(false),detailError=ref(''),memory=ref(null);
const revokeSource=ref(null),reason=ref(''),saving=ref(false),revokeError=ref(''),retrying=ref('');
const editor=ref(null),form=ref({}),conditionsText=ref(''),formError=ref(''),operation=ref(null),operationNote=ref(''),operationError=ref('');
let timer,searchTimer,detailSequence=0,loadSequence=0,memorySequence=0,disposed=false;
const visibleMemories=computed(()=>data.value.memories);
const filteredSystemSkills=computed(()=>systemSkills.value.filter(item=>{
 if(!['all','system'].includes(kind.value)||!['all','active'].includes(state.value)||!['all','none'].includes(review.value))return false;
 return [item.title,item.name,item.description,item.content,...Object.values(item.resources)].join(' ').toLowerCase().includes(query.value.trim().toLowerCase());
}));
const visibleSystemSkills=computed(()=>page.value===1?filteredSystemSkills.value:[]);
const knowledgeTotal=computed(()=>data.value.total+filteredSystemSkills.value.length);
const pages=computed(()=>Math.max(1,Math.ceil(data.value.total/data.value.pageSize)));
const tabs=[{id:'all',label:'全部'},{id:'skill',label:'审查技能'},{id:'experience',label:'案例经验'},{id:'system',label:'系统技能'}];
const sourceLabel=k=>({legal_decision:'确认法务结论',finding_disposition:'处理审查意见',saved_revision:'保存合同改稿',review_revision:'在线审阅与修改',explicit_feedback:'明确法务反馈'}[k]||'法务处理');
const kindLabel=k=>({skill:'审查技能',experience:'案例经验',system:'系统技能'})[k]||k;
const displayKind=m=>m.is_system?'system':preview(m).kind;
const preview=m=>m.version?m:(m.draft||m);
const reviewLabel=s=>({none:'无待处理草稿',draft:'草稿',pending:'待审核',rejected:'已退回',published:'已发布'}[s]||s);
const stateLabel=m=>m.revoked_at||m.state==='revoked'?'来源已撤销':!m.version?'未发布':m.state==='active'?'生效中':'已停用';
const actionLabels={edit:'编辑',submit:'提交审核',approve:'审核通过',reject:'退回修改',enable:'启用',disable:'停用',delete:'删除',promote:'设为系统技能',demote:'切回审查技能'};
function actions(m){if(m.revoked_at||m.state==='revoked')return ['delete'];return [...(m.draft_status==='pending'?['approve','reject']:['edit',...(['draft','rejected'].includes(m.draft_status)?['submit']:[])]),...(m.is_system?['demote']:m.kind==='skill'&&m.version&&m.state==='active'&&m.draft_status==='none'?['promote']:[]),...(m.version?[m.state==='active'?'disable':'enable']:[]),'delete'];}
const resultLabel=s=>s.revoked_at?'来源已撤销':({queued:'等待整理',running:'正在整理',failed:'整理失败'}[s.status]||(s.generatedCount?(s.pendingKnowledgeCount?'已生成 · 待审核':'已生成'):'未生成'));
const resultClass=s=>s.revoked_at?'revoked':s.status==='completed'?(s.generatedCount?'generated':'empty'):s.status;
const shortResult=s=>s.revoked_at?'该来源产生的内容已停止复用':s.resultCode==='NO_SUBSTANTIVE_FEEDBACK'?'未填写处理理由或附加条件':s.status==='completed'&&!s.generatedCount?'未提炼出可复用内容':s.resultText;
async function load(quiet=false){
 const sequence=++loadSequence;refreshing.value=true;clearTimeout(timer);
 try{const filters=new URLSearchParams({q:query.value,kind:kind.value,state:state.value,review:review.value,page:String(page.value),pageSize:'20'});const [result,builtins]=await Promise.all([api('/agent/experiences?'+filters,{quiet:true}),api('/agent/system-skills',{quiet:true})]);if(!disposed&&sequence===loadSequence){data.value=result;systemSkills.value=builtins.skills;page.value=result.page;error.value='';if(sourceId.value&&['queued','running'].includes(detail.value?.status)){const id=sourceId.value,ds=detailSequence;const source=await api('/agent/experience-sources/'+id,{quiet:true});if(!disposed&&ds===detailSequence&&id===sourceId.value)detail.value=source;}}}
 catch(e){if(!disposed&&sequence===loadSequence)error.value=e.message;}
 finally{if(sequence===loadSequence){loading.value=false;refreshing.value=false;if(!disposed&&data.value.summary.pending)timer=setTimeout(()=>load(true),5000);}}
}
function filterChanged(){clearTimeout(searchTimer);page.value=1;load();}
watch([kind,state,review],filterChanged);
watch(query,()=>{clearTimeout(searchTimer);searchTimer=setTimeout(filterChanged,300);});
function changePage(value){page.value=value;load();}
async function openMemory(id){const sequence=++memorySequence;try{const result=await api('/agent/experiences/'+id,{quiet:true});if(!disposed&&sequence===memorySequence)memory.value=result;}catch(e){error.value=e.message;}}
async function editMemory(item=null){
 formError.value='';saving.value=true;
 try{const value=item?await api('/agent/experiences/'+item.id,{quiet:true}):null;if(value?.draft_status==='pending')throw new Error('待审核内容已锁定，请先退回修改');editor.value=value||{id:null};form.value={...(value?.draft||value||{kind:kind.value==='experience'?'experience':'skill',title:'',description:'',content:'',conditions:[]}),department:value?.department??(session.user?.department==='*'?'':session.user?.department||'')};conditionsText.value=(form.value.conditions||[]).join('\n');}
 catch(e){error.value=e.message;}finally{saving.value=false;}
}
async function saveMemory(){
 if(saving.value)return;saving.value=true;formError.value='';
 try{const value=await api('/agent/experiences'+(editor.value.id?'/'+editor.value.id:''),{method:editor.value.id?'PUT':'POST',body:{kind:form.value.kind,title:form.value.title,description:form.value.description,content:form.value.content,conditions:conditionsText.value.split('\n').map(s=>s.trim()).filter(Boolean),...(editor.value.id?{revision:editor.value.revision}:{department:form.value.department})},quiet:true});editor.value=null;await load();await openMemory(value.id);}
 catch(e){formError.value=e.message;}finally{saving.value=false;}
}
async function act(item,action){
 if(action==='edit')return editMemory(item);
 operation.value={item,action};operationNote.value='';operationError.value='';
}
async function perform(){
 if(saving.value||!operation.value)return;saving.value=true;operationError.value='';
 const {item,action}=operation.value;
 try{await api('/agent/experiences/'+item.id+(action==='delete'?'':'/'+action),{method:action==='delete'?'DELETE':'POST',body:{revision:item.revision,note:operationNote.value},quiet:true});operation.value=null;if(action==='delete'){if(memory.value?.id===item.id)memory.value=null;}else if(memory.value?.id===item.id)await openMemory(item.id);await load();if(sourceId.value)await openSource(sourceId.value);}
 catch(e){operationError.value=e.message;}finally{saving.value=false;}
}
async function openSource(id){
 const sequence=++detailSequence;sourceId.value=id;detail.value=null;detailError.value='';detailLoading.value=true;
 try{const result=await api('/agent/experience-sources/'+id,{quiet:true});if(sequence===detailSequence)detail.value=result;}
 catch(e){if(sequence===detailSequence)detailError.value=e.message;}
 finally{if(sequence===detailSequence)detailLoading.value=false;}
}
function closeSource(){sourceId.value='';detailSequence++;}
async function retry(id){if(retrying.value)return;retrying.value=id;try{const source=await api('/agent/experience-sources/'+id,{quiet:true});await api('/agent/experience-sources/'+id+'/retry',{method:'POST',body:{revision:source.revision},quiet:true});await load();if(sourceId.value===id)await openSource(id);}catch(e){error.value=e.message;}finally{retrying.value='';}}
async function requestRevoke(item){try{revokeSource.value=await api('/agent/experience-sources/'+(item.source_id||item.id),{quiet:true});reason.value='';revokeError.value='';}catch(e){error.value=e.message;}}
async function revoke(){if(saving.value||!reason.value.trim())return;saving.value=true;try{await api('/agent/experience-sources/'+revokeSource.value.id+'/revoke',{method:'POST',body:{reason:reason.value,revision:revokeSource.value.revision},quiet:true});revokeSource.value=null;memory.value=null;await load();if(sourceId.value)await openSource(sourceId.value);}catch(e){revokeError.value=e.message;}finally{saving.value=false;}}
watch(()=>route.query.source,id=>{if(typeof id==='string' && /^[0-9a-f-]{36}$/i.test(id))openSource(id);},{immediate:true});
onMounted(()=>load());onUnmounted(()=>{disposed=true;clearTimeout(timer);clearTimeout(searchTimer);detailSequence++;memorySequence++;loadSequence++;});
</script>

<template>
<div class="experience-page">
 <section class="page-heading experience-heading"><div><div class="eyebrow">KNOWLEDGE &amp; LEARNING</div><h1>法务经验</h1><p>管理可复用的审查方法、案例判断与每一次自动整理。</p></div><div class="experience-actions"><router-link to="/experience/history">历史知识库 ↗</router-link><button :disabled="refreshing" @click="load()"><Icon name="refresh" />{{refreshing&&!loading?'刷新中…':'刷新'}}</button><button class="primary" :disabled="saving" @click="editMemory()">新增知识</button></div></section>
 <p v-if="error" role="alert" class="notice danger">{{error}}</p>
 <div v-if="loading" class="experience-loading" role="status">正在加载法务经验与整理记录…</div>
 <template v-else>
  <section class="experience-metrics" aria-label="法务经验概览">
   <article><span class="metric-icon blue"><Icon name="book" /></span><div><span>生效中的审查技能</span><strong>{{String(data.summary.skills).padStart(2,'0')}}</strong><small>可执行的审查方法</small></div></article>
   <article><span class="metric-icon violet"><Icon name="layers" /></span><div><span>生效中的案例经验</span><strong>{{String(data.summary.experiences).padStart(2,'0')}}</strong><small>带适用条件的判断依据</small></div></article>
   <article><span class="metric-icon slate"><Icon name="history" /></span><div><span>自动整理记录</span><strong>{{String(data.summary.sources).padStart(2,'0')}}</strong><small>{{data.summary.pending?`${data.summary.pending} 条正在后台处理`:'每次处理都有迹可循'}}</small></div></article>
   <article><span class="metric-icon blue"><Icon name="check" /></span><div><span>待审核知识</span><strong>{{String(data.summary.pendingReview).padStart(2,'0')}}</strong><small>审核通过后供后续审查使用</small></div></article>
  </section>
  <section class="panel learning-records" aria-labelledby="records-heading"><header class="experience-panel-heading"><div><h2 id="records-heading">自动整理记录 <span class="records-count">{{data.sourceCount}}</span></h2><p>查看每次处理的来源、生成结果和未生成的原因。</p></div><span class="records-caption">最近 {{data.sources.length}} 条</span></header><div v-if="!data.sources.length" class="records-empty"><Icon name="history" /><p>保存第一条法务处理后，这里会显示整理进度。</p></div><div v-else class="records-table-wrap"><table class="records-table"><thead><tr><th>来源合同 / 法务处理</th><th>整理结果</th><th>生成内容</th><th>整理时间</th><th><span class="sr-only">操作</span></th></tr></thead><tbody><tr v-for="item in data.sources" :key="item.id"><td><div class="record-source"><span class="record-icon"><Icon name="file" /></span><div><strong :title="item.contract_title">{{item.contract_title}}</strong><span>{{sourceLabel(item.kind)}}</span></div></div></td><td><span class="result-status" :class="resultClass(item)"><i></i>{{resultLabel(item)}}</span><p class="record-result-text">{{shortResult(item)}}</p></td><td><div v-if="item.status==='completed'" class="generated-counts"><span>技能 <b>{{item.skillCount}}</b></span><span>经验 <b>{{item.experienceCount}}</b></span></div><span v-else class="records-caption">—</span></td><td class="record-time">{{time(item.updated_at||item.created_at)}}</td><td><div class="record-actions"><button @click="openSource(item.id)">查看详情 ↗</button><button v-if="item.status==='failed'&&!item.revoked_at" :disabled="!!retrying" @click="retry(item.id)">{{retrying===item.id?'提交中…':'重试整理'}}</button></div></td></tr></tbody></table></div></section>
  <div class="experience-layout">
   <section class="panel knowledge-panel" aria-labelledby="knowledge-heading">
    <header class="experience-panel-heading"><div><h2 id="knowledge-heading">可复用知识 <span class="records-count">{{knowledgeTotal}}</span></h2><p>系统技能在适用审查中必读；生效审查技能可设为系统技能，也可切回。</p></div><span class="subtle-pill"><i></i>{{kind==='system'?'系统必读':'按来源复用'}}</span></header>
    <div class="knowledge-toolbar"><div class="knowledge-tabs" role="group" aria-label="知识类型"><button v-for="tab in tabs" :key="tab.id" :aria-pressed="kind===tab.id" :class="{selected:kind===tab.id}" @click="kind=tab.id">{{tab.label}}</button></div><label class="knowledge-search"><Icon name="search" /><input v-model="query" aria-label="搜索技能或经验" placeholder="搜索标题、正文、适用条件" /></label><div class="knowledge-filters"><label>生效状态<select v-model="state" aria-label="生效状态"><option value="all">全部状态</option><option value="active">生效中</option><option value="disabled">已停用 / 来源已撤销</option><option value="unpublished">未发布</option></select></label><label>审核状态<select v-model="review" aria-label="审核状态"><option value="all">全部审核状态</option><option value="draft">草稿</option><option value="pending">待审核</option><option value="rejected">已退回</option><option value="none">无待处理草稿</option></select></label></div></div>
    <div v-if="!visibleMemories.length&&!visibleSystemSkills.length" class="knowledge-empty"><span class="empty-book"><Icon name="book" /></span><h3>没有找到相关知识</h3><p>可调整搜索和筛选条件，或新增审查技能、案例经验。</p><button v-if="kind!=='system'" class="primary" :disabled="saving" @click="editMemory()">新增知识</button></div>
    <div v-else class="knowledge-cards"><article v-for="item in visibleSystemSkills" :key="item.name" class="knowledge-card"><div class="knowledge-card-top"><span class="knowledge-kind system">系统技能</span><span class="memory-state">已生效 · 必读</span></div><button class="knowledge-title" @click="systemSkill=item">{{item.title}}</button><p>{{item.description}}</p><div class="condition-tags"><span>{{item.scope==='all_reviews'?'每轮合同审查必读':'自动评审批次必读'}}</span><span>正文与参考资料固定版本</span></div><div class="knowledge-card-footer"><button @click="systemSkill=item">查看技能与范例 ↗</button><span>版本 {{item.version}}</span></div></article><article v-for="item in visibleMemories" :key="item.id" class="knowledge-card"><div class="knowledge-card-top"><span class="knowledge-kind" :class="displayKind(item)">{{kindLabel(displayKind(item))}}</span><span class="memory-state">{{stateLabel(item)}}<template v-if="item.version"> · v{{item.version}}</template></span></div><button class="knowledge-title" :disabled="saving" @click="openMemory(item.id)">{{preview(item).title}}</button><p>{{preview(item).description}}</p><div class="memory-badges"><span>{{item.origin==='manual'?'人工创建':'自动提炼'}}</span><span v-if="item.draft_status!=='none'" :class="item.draft_status">{{reviewLabel(item.draft_status)}}<template v-if="item.draft&&item.version">：{{item.draft.title}}</template></span><span>{{item.department||'未设置部门'}}</span><span v-if="item.is_system">每轮必读 · 按适用条件执行</span></div><div class="condition-tags"><span v-for="condition in preview(item).conditions.slice(0,2)" :key="condition">{{condition}}</span></div><div class="knowledge-row-actions"><button v-for="action in actions(item)" :key="action" :class="{danger:action==='delete'}" :disabled="saving" @click="act(item,action)">{{actionLabels[action]}}</button></div><div class="knowledge-card-footer"><button v-if="item.source_id" @click="openSource(item.source_id)">查看整理来源 ↗</button><span v-else>人工创建</span><span>{{time(item.updated_at)}}</span></div></article></div>
    <nav v-if="kind!=='system'||data.total>0" class="knowledge-pagination" aria-label="知识分页"><span>共 {{data.total}} 条 · 第 {{data.page}} / {{pages}} 页</span><button :disabled="page<=1||refreshing" @click="changePage(page-1)">上一页</button><button :disabled="page>=pages||refreshing" @click="changePage(page+1)">下一页</button></nav>
   </section>
   <aside class="learning-guide" aria-labelledby="guide-heading"><span class="guide-caption">从处理到积累</span><h2 id="guide-heading">知识如何管理？</h2><ol><li><span class="step-number">01</span><div><h3>新增或自动提炼</h3><p>手工录入知识，或从法务已保存的处理提炼草稿。</p></div></li><li><span class="step-number">02</span><div><h3>提交并审核</h3><p>核对方法、适用条件与来源，审核通过后生效；退回内容可修改重提。</p></div></li><li><span class="step-number">03</span><div><h3>持续维护</h3><p>修改生成新草稿，原正式版继续使用。支持单条启停和永久删除。</p></div></li></ol><div class="guide-note"><Icon name="info" /><p>删除知识将清除其内容和版本记录；已有审查保留当时的内容快照。撤销整个来源会停用该来源下所有知识。</p></div></aside>
  </div>
 </template>
 <el-dialog :model-value="!!systemSkill" @close="systemSkill=null" title="系统技能详情" width="min(900px, calc(100vw - 32px))"><div v-if="systemSkill" class="memory-detail"><div class="memory-badges"><span>系统技能</span><span>{{systemSkill.scope==='all_reviews'?'每轮合同审查必读':'自动评审批次必读'}}</span><span>固定版本 {{systemSkill.version}}</span></div><h2>{{systemSkill.title}}</h2><p>{{systemSkill.description}}</p><p class="muted">内置系统技能随项目维护；审查记录保留当轮版本。自行提升的系统技能可在列表中编辑、停用或切回。</p><section class="memory-version"><h3>技能正文</h3><p class="memory-content">{{systemSkill.content}}</p></section><section v-for="(content,name) in systemSkill.resources" :key="name" class="memory-version"><h3>必读范例</h3><p class="memory-content">{{content}}</p></section></div></el-dialog>
 <el-drawer :model-value="!!sourceId" @close="closeSource" title="自动整理详情" size="min(560px, 100vw)" class="experience-drawer">
  <p v-if="detailLoading" role="status">正在加载整理详情…</p><p v-else-if="detailError" role="alert" class="notice danger">{{detailError}}</p>
  <div v-else-if="detail" class="source-detail"><div class="detail-source"><span class="knowledge-kind">{{sourceLabel(detail.kind)}}</span><h2>{{detail.contract_title}}</h2><span class="result-status" :class="resultClass(detail)"><i></i>{{resultLabel(detail)}}</span></div><section class="detail-result"><h3>整理结果</h3><p>{{detail.resultText}}</p><div class="detail-counts"><span><b>{{detail.skillCount}}</b> 条审查技能</span><span><b>{{detail.experienceCount}}</b> 条案例经验</span></div><p v-if="detail.error" class="detail-error">错误信息：{{detail.error}}</p><p v-if="detail.revoked_at" class="detail-error">该来源已撤销，派生内容已停止复用。</p></section><section class="detail-input"><h3>本次保存的法务处理</h3><dl><div v-for="field in detail.fields" :key="field.label"><dt>{{field.label}}</dt><dd :class="{unfilled:!field.value}">{{field.value||'未填写'}}</dd></div></dl></section><section v-if="detail.memories.length" class="detail-generated"><h3>生成的内容</h3><article v-for="item in detail.memories" :key="item.id"><span class="knowledge-kind">{{kindLabel(displayKind(item))}}</span><h4>{{item.title}}</h4><p>{{item.description}}</p><p v-if="item.sourceQuotes?.length" class="memory-content">初次提炼依据：{{item.sourceQuotes.join("；")}}</p><details><summary>查看完整内容</summary><p class="memory-content">{{item.content}}</p></details><div class="knowledge-row-actions"><span class="memory-state">{{stateLabel(item)}} · {{reviewLabel(item.draft_status)}}</span><button @click="closeSource();openMemory(item.id)">查看并管理知识</button></div></article></section><div class="detail-times"><span>来源保存于 {{time(detail.created_at)}}</span><span>最近处理于 {{time(detail.updated_at)}}</span></div><div class="detail-links"><router-link :to="'/contracts/'+detail.contract_id">查看合同与法务处理 <Icon name="arrow" /></router-link><button v-if="detail.status==='failed'&&!detail.revoked_at" :disabled="!!retrying" @click="retry(detail.id)">重试整理</button></div></div>
 </el-drawer>
 <el-dialog :model-value="!!memory" @close="memory=null;memorySequence++" title="知识详情" width="min(800px, calc(100vw - 32px))"><div v-if="memory" class="memory-detail"><div class="memory-badges"><span>{{memory.origin==='manual'?'人工创建':'自动提炼'}}</span><span>{{stateLabel(memory)}}</span><span>{{reviewLabel(memory.draft_status)}}</span><span>{{kindLabel(displayKind(memory))}}</span><span>{{memory.department||'未设置部门'}}</span></div><h2>{{preview(memory).title}}</h2><section v-if="memory.version" class="memory-version"><h3>当前正式版本 · v{{memory.version}} · {{kindLabel(displayKind(memory))}}</h3><p>{{memory.description}}</p><div class="condition-tags"><span v-for="condition in memory.conditions" :key="condition">{{condition}}</span></div><p class="memory-content">{{memory.content}}</p></section><section v-if="memory.draft" class="memory-version draft-version"><h3>{{reviewLabel(memory.draft_status)}} · {{kindLabel(memory.draft.kind)}}</h3><h4>{{memory.draft.title}}</h4><p>{{memory.draft.description}}</p><div class="condition-tags"><span v-for="condition in memory.draft.conditions" :key="condition">{{condition}}</span></div><p class="memory-content">{{memory.draft.content}}</p></section><div class="knowledge-row-actions"><button v-for="action in actions(memory)" :key="action" :class="{danger:action==='delete'}" :disabled="saving" @click="act(memory,action)">{{actionLabels[action]}}</button></div><div class="detail-links" v-if="memory.source_id"><button @click="openSource(memory.source_id)">查看整理来源</button><button v-if="!memory.revoked_at" :disabled="saving" @click="requestRevoke(memory)">撤销整个来源</button></div><section class="memory-version"><h3>版本与审核意见</h3><details v-for="version in memory.versions" :key="version.id"><summary>v{{version.version}} · {{reviewLabel(version.status)}} · {{time(version.updated_at)}}</summary><p v-if="version.review_note">审核意见：{{version.review_note}}</p><h4>{{version.body.title}}</h4><p>{{version.body.description}}</p><p class="memory-content">{{version.body.content}}</p><div class="condition-tags"><span v-for="condition in version.body.conditions" :key="condition">{{condition}}</span></div></details></section><section class="memory-version"><h3>操作记录</h3><ol class="memory-history"><li v-for="(record,index) in memory.history" :key="index"><b>{{({'agent.memory.create':'创建草稿','agent.memory.edit':'编辑草稿','agent.memory.submit':'提交审核','agent.memory.approve':'审核通过','agent.memory.reject':'退回修改','agent.memory.enable':'启用','agent.memory.disable':'停用','agent.memory.source_revoke':'来源已撤销','agent.memory.promote':'设为系统技能','agent.memory.demote':'切回审查技能'})[record.action]||record.action}}</b> · {{record.actor||'系统'}} · {{time(record.created_at)}}<p v-if="record.details.note">{{record.details.note}}</p></li></ol><p v-if="!memory.history.length">历史导入版本，暂无操作记录。</p></section></div></el-dialog>
 <el-dialog :model-value="!!editor" @close="editor=null" :title="editor?.id?'编辑知识草稿':'新增知识'" width="min(720px, calc(100vw - 32px))" :close-on-click-modal="false" :close-on-press-escape="!saving" :show-close="!saving"><form v-if="editor" class="stack memory-form" @submit.prevent="saveMemory"><p class="muted">保存为草稿，提交并审核通过后用于审查。已有正式版本继续有效。</p><label>知识类型<select aria-label="知识类型" v-model="form.kind" :disabled="saving||editor.is_system"><option value="skill">审查技能</option><option value="experience">案例经验</option></select></label><label v-if="!editor.id&&(role('admin')||session.user?.department==='*')">所属部门<input v-model="form.department" maxlength="200" :disabled="saving" placeholder="与使用该知识的合同所属部门一致；可留空" /></label><label>标题<input v-model="form.title" required maxlength="200" :disabled="saving" /></label><label>摘要<textarea v-model="form.description" required maxlength="500" rows="3" :disabled="saving" /></label><label>完整内容<textarea v-model="form.content" required maxlength="12000" rows="8" :disabled="saving" /></label><label>适用条件（每行一条，最多 20 条，每条最多 1000 字）<textarea v-model="conditionsText" rows="4" :disabled="saving" /></label><p v-if="formError" role="alert" class="notice danger">{{formError}}</p><div class="knowledge-row-actions"><button class="primary" type="submit" :disabled="saving">{{saving?'正在保存…':'保存草稿'}}</button><button type="button" :disabled="saving" @click="editor=null">取消</button></div></form></el-dialog>
 <el-dialog :model-value="!!operation" @close="operation=null" :title="operation? actionLabels[operation.action]+(['promote','demote'].includes(operation.action)?'':'知识'):''" width="min(540px, calc(100vw - 32px))" :close-on-click-modal="!saving" :close-on-press-escape="!saving" :show-close="!saving"><form v-if="operation" class="stack" @submit.prevent="perform"><h3>{{operation.item.draft?.title||operation.item.title}}</h3><p v-if="operation.action==='delete'">永久删除将清除本条知识及全部草稿、版本正文，无法恢复。已有审查保留当时的内容快照并标记待复核，同来源其他知识不受影响。</p><p v-else-if="operation.action==='approve'">审核通过后发布新版本，后续审查将按启用状态使用。已使用旧版的审查会标记待复核。</p><p v-else-if="operation.action==='submit'">提交后内容锁定，待法务或管理员审核。允许审核本人提交的内容。</p><p v-else-if="operation.action==='disable'">停用本条知识，后续审查不再加载，相关审查标记待复核。</p><p v-else-if="operation.action==='promote'">设为系统技能后，同部门后续每轮审查都会加载本条方法，并按原有适用条件执行。正文、来源和正式版本保留；已有相关审查标记待复核。</p><p v-else-if="operation.action==='demote'">切回后，后续审查将按需读取本条方法。正文、来源、版本和启停状态保留；已有相关审查标记待复核。</p><p v-else-if="operation.action==='enable'">启用已审核的正式版本，后续审查即可使用。</p><label v-if="['approve','reject'].includes(operation.action)">{{operation.action==='reject'?'退回原因（必填）':'审核意见（选填）'}}<textarea v-model="operationNote" :required="operation.action==='reject'" maxlength="3000" rows="4" :disabled="saving" /></label><p v-if="operationError" role="alert" class="notice danger">{{operationError}}</p><div class="knowledge-row-actions"><button class="primary" :disabled="saving||(operation.action==='reject'&&!operationNote.trim())">{{saving?'正在处理…':operation.action==='delete'?'确认永久删除':'确认'+actionLabels[operation.action]}}</button><button type="button" :disabled="saving" @click="operation=null">取消</button></div></form></el-dialog>
 <el-dialog :model-value="!!revokeSource" @close="revokeSource=null" title="撤销经验来源" width="min(540px, calc(100vw - 32px))" :close-on-click-modal="!saving" :close-on-press-escape="!saving" :show-close="!saving"><form class="stack" @submit.prevent="revoke"><p>该来源派生的技能和经验将停止复用，已引用的审查结果会标记需要重新核查。</p><label>撤销原因<textarea v-model="reason" required maxlength="3000" rows="4" :disabled="saving" /></label><p v-if="revokeError" role="alert" class="notice danger">{{revokeError}}</p><button class="primary" :disabled="saving||!reason.trim()">{{saving?'正在撤销…':'确认撤销来源'}}</button></form></el-dialog>
</div>
